interface SortStrategy { fun sort(data: MutableList<Int>) }

class BubbleSort : SortStrategy {
    override fun sort(data: MutableList<Int>) { /* bubble sort */ }
}
class QuickSort : SortStrategy {
    override fun sort(data: MutableList<Int>) { /* quick sort */ }
}

class Sorter(private var strategy: SortStrategy) {
    fun setStrategy(s: SortStrategy) { strategy = s }
    fun sort(data: MutableList<Int>) = strategy.sort(data)
}

val sorter = Sorter(BubbleSort())
sorter.sort(list)
sorter.setStrategy(QuickSort()) // Swap strategy at runtime
sorter.sort(list)

